      "type": "array",
      "description": "Liste des rôles principaux ciblés.",
      "items": {
        "type": "string"
      }
    },
    "secondaryRoles": {
      "type": "array",
      "description": "Liste des rôles secondaires ou connexes.",
      "items": {
        "type": "string"
      }
    },
    "coreSkills": {
      "type": "array",
      "description": "Compétences clés requises pour le poste.",
      "items": {
