{
  "type": "object",
  "properties": {
    "queries": {
      "type": "array",
      "minItems": 6,
      "maxItems": 10,
      "items": {
        "type": "object",
        "required": ["q"],
        "properties": {
          "q": { "type": "string", "description": "Search text for Google Jobs (job title + keyword variant, max 4-5 words)" },
          "location": { "type": "string", "description": "City/region string, e.g. 'Istanbul, Turkey'. Omit for remote-only queries." }
